  /** Returns array of page indices to show in the pagination bar (max 9 buttons, windowed). */
  getPaginationPages(): number[] {
    const total = this.workbook.getPageCount();
    const current = this.workbook.whichPage();
    const maxButtons = 9;
    if (total <= maxButtons) return Array.from({ length: total }, (_, i) => i);
    const half = Math.floor(maxButtons / 2);
    let start = Math.max(0, current - half);
    const end = Math.min(total - 1, start + maxButtons - 1);
    start = Math.max(0, end - maxButtons + 1);
    return Array.from({ length: end - start + 1 }, (_, i) => start + i);
  }

  /** Returns the "Showing page X of Y" label for the pagination bar. */
  paginationLabel(): string {
    const tpl = this.workbook.getText('showingPage' as any) ?? 'Pagina {0} di {1}';
    return tpl.replace('{0}', String(this.workbook.whichPage() + 1)).replace('{1}', String(this.workbook.getPageCount()));
  }

