  private _applyToolbarStyle(prop: string, value: string): void {
    const sel = this.workbook.getSelection();
    if (!sel) return;
    const { x1, y1, x2, y2 } = sel;
    for (let y = Math.min(y1, y2); y <= Math.max(y1, y2); y++) {
      for (let x = Math.min(x1, x2); x <= Math.max(x1, x2); x++) {
        this.workbook.setCellStyle(this.cellName(x, y), { [prop]: value });
      }
    }
  }
