import {
  AfterViewInit,
  Component,
  ElementRef,
  EventEmitter,
  Input,
  OnChanges,
  Output,
  SimpleChanges,
  ViewChild,
} from "@angular/core";

import { JxColumn } from "../../models/jx-column.model";
import { JxGridOptions } from "../../models/jx-grid-options.model";
import {
  JxCellActionEvent,
  JxCellChangeEvent,
} from "../../models/jx-cell-event.model";

/** Number of rows rendered above and below the visible viewport as a scroll buffer. */
const VIRTUAL_BUFFER = 5;
/** Fallback row height in pixels when `options.rowHeight` is not provided. */
const DEFAULT_ROW_HEIGHT = 40;

/**
 * Lightweight data-grid component for displaying and editing typed row arrays.
 *
 * `JxGridComponent` is the Angular-native counterpart of `JxTableComponent`.
 * Rather than wrapping the jtable library, it renders rows via Angular's
 * own `*ngFor` + a dynamic cell-host (`<jx-cell-host>`) so Angular change
 * detection and DI work seamlessly.
 *
 * ## Features
 * - Strongly-typed columns via `JxColumn<T>`
 * - Built-in cell types: `text`, `number`, `checkbox`, `formula`, `button`, `attachment`
 * - Custom cell components via `column.component`
 * - Virtual scrolling — renders only the visible window (+ 5-row buffer),
 *   keeping DOM node count constant for any dataset size
 * - Row selection, column hide/show, editable guard
 * - `cellChange`, `cellAction`, `rowSelect` outputs
 *
 * ## Usage
 * ```html
 * <jx-grid
 *   [data]="rows"
 *   [columns]="columns"
 *   [options]="opts"
 *   (cellChange)="onChange($event)"
 *   (rowSelect)="onSelect($event)">
 * </jx-grid>
 * ```
 *
 * ## Virtual scroll example
 * ```typescript
 * opts: JxGridOptions = {
 *   virtualScroll: true,
 *   virtualScrollHeight: '480px',
 *   rowHeight: 40,
 * };
 * ```
 *
 * @template T  Row object type — must extend `Record<string, any>`.
 */
@Component({
  standalone: false,
  selector: "jx-grid",
  templateUrl: "./jx-grid.component.html",
  styleUrls: ["./jx-grid.component.scss"],
})
export class JxGridComponent<
  T extends Record<string, any> = any,
> implements OnChanges, AfterViewInit {
  /** The full row dataset. Only the visible window is rendered when `virtualScroll` is on. */
  @Input() data: T[] = [];
  /** Column definitions that control rendering, editing, and width of each column. */
  @Input() columns: JxColumn<T>[] = [];
  /** Grid behaviour options (editable, selectable, virtual scroll, row height, …). */
  @Input() options: JxGridOptions = {};

  /** Emits when the user commits a cell edit. */
  @Output() cellChange = new EventEmitter<JxCellChangeEvent<T>>();
  /** Emits when a button/action cell is triggered. */
  @Output() cellAction = new EventEmitter<JxCellActionEvent<T>>();
  /** Emits the clicked row when `options.selectable` is `true`. */
  @Output() rowSelect = new EventEmitter<T>();

  @ViewChild("scrollContainer") private scrollContainerRef?: ElementRef<HTMLElement>;

  visibleColumns: JxColumn<T>[] = [];
  selectedRowIndex: number | null = null;

  // ── Virtual scroll state ─────────────────────────────────────────────────
  /** The currently rendered slice of `data`. Equals `data` when virtual scroll is off. */
  virtualRows: T[] = [];
  /** Data index of the first row in `virtualRows`. */
  startIndex = 0;
  /** Pixel height of the empty spacer row rendered above the visible slice. */
  paddingTop = 0;
  /** Pixel height of the empty spacer row rendered below the visible slice. */
  paddingBottom = 0;

  // ── Computed helpers ──────────────────────────────────────────────────────
  /** `true` when virtual scrolling is active (`options.virtualScroll === true`). */
  get isVirtualScroll(): boolean {
    return !!this.options.virtualScroll;
  }

  /**
   * The row slice currently bound to `*ngFor` in the template.
   * - Virtual scroll ON → `virtualRows` (the current window).
   * - Virtual scroll OFF → the full `data` array.
   */
  get visibleRows(): T[] {
    return this.isVirtualScroll ? this.virtualRows : this.data;
  }

  /**
   * Maps a local `*ngFor` index (0-based within the rendered slice) to the
   * true index within the full `data` array.
   * When virtual scroll is off this is an identity function.
   *
   * @param localIndex - Index from `*ngFor let i = index`.
   * @returns Absolute data index.
   */
  getActualRowIndex(localIndex: number): number {
    return this.isVirtualScroll ? this.startIndex + localIndex : localIndex;
  }

  // ── Lifecycle ─────────────────────────────────────────────────────────────
  ngOnChanges(changes: SimpleChanges): void {
    if (changes["columns"]) {
      this.visibleColumns = this.columns.filter((column) => !column.hidden);
    }
    if (changes["data"] || changes["options"]) {
      if (this.isVirtualScroll) {
        const scrollTop = this.scrollContainerRef?.nativeElement.scrollTop ?? 0;
        this.updateVirtualWindow(scrollTop);
      }
    }
  }

  ngAfterViewInit(): void {
    if (this.isVirtualScroll) {
      this.updateVirtualWindow(0);
    }
  }

  // ── Virtual scroll core ───────────────────────────────────────────────────
  /**
   * Scroll event handler attached to the container element when virtual scroll
   * is active.  Delegates to `updateVirtualWindow()`.
   *
   * @param event - Native DOM scroll event.
   */
  onScroll(event: Event): void {
    this.updateVirtualWindow((event.target as HTMLElement).scrollTop);
  }

  /**
   * Recalculates the rendered window based on the current scroll position.
   *
   * **Algorithm:**
   * 1. Determine the first visible row index from `scrollTop / rowH`.
   * 2. Expand by `VIRTUAL_BUFFER` rows on each side.
   * 3. Clamp to `[0, data.length]`.
   * 4. Set `virtualRows` to `data.slice(start, end)`.
   * 5. Set `paddingTop` / `paddingBottom` spacer heights so the total
   *    scrollable height equals `data.length * rowH`.
   *
   * @param scrollTop - Current vertical scroll offset in pixels.
   */
  private updateVirtualWindow(scrollTop: number): void {
    const rowH = this.options.rowHeight ?? DEFAULT_ROW_HEIGHT;
    const containerH = this.scrollContainerRef?.nativeElement.clientHeight ?? 400;
    const visibleCount = Math.ceil(containerH / rowH);

    const rawStart = Math.floor(scrollTop / rowH) - VIRTUAL_BUFFER;
    const start = Math.max(0, rawStart);
    const end = Math.min(this.data.length, start + visibleCount + VIRTUAL_BUFFER * 2);

    this.startIndex = start;
    this.virtualRows = this.data.slice(start, end);
    this.paddingTop = start * rowH;
    this.paddingBottom = Math.max(0, (this.data.length - end) * rowH);
  }

  // ── Grid helpers ──────────────────────────────────────────────────────────
  getValue(row: T, column: JxColumn<T>): any {
    return row[column.key as keyof T];
  }

  getColumnWidth(column: JxColumn<T>): string | null {
    if (!column.width) {
      return null;
    }

    return typeof column.width === "number"
      ? `${column.width}px`
      : column.width;
  }

  getRowHeight(): string | null {
    return this.options.rowHeight ? `${this.options.rowHeight}px` : null;
  }

  isEditable(column: JxColumn<T>): boolean {
    return !!this.options.editable && column.editable !== false;
  }

  getCellClass(column: JxColumn<T>): string {
    return column.cssClass ?? "";
  }

  getHeaderClass(column: JxColumn<T>): string {
    return column.headerCssClass ?? "";
  }

  onCellValueChange(
    row: T,
    localIndex: number,
    column: JxColumn<T>,
    columnIndex: number,
    newValue: any,
  ): void {
    const key = column.key as keyof T;
    const oldValue = row[key];

    if (oldValue === newValue) {
      return;
    }

    row[key] = newValue;

    this.cellChange.emit({
      row,
      rowIndex: this.getActualRowIndex(localIndex),
      column,
      columnIndex,
      oldValue,
      newValue,
    });
  }

  onCellAction(
    row: T,
    localIndex: number,
    column: JxColumn<T>,
    columnIndex: number,
    event: any,
  ): void {
    this.cellAction.emit({
      row,
      rowIndex: this.getActualRowIndex(localIndex),
      column,
      columnIndex,
      value: this.getValue(row, column),
      action: event?.action ?? "action",
      payload: event?.payload,
    });
  }

  selectRow(row: T, localIndex: number): void {
    if (!this.options.selectable) {
      return;
    }

    this.selectedRowIndex = this.getActualRowIndex(localIndex);
    this.rowSelect.emit(row);
  }

  trackByRow = (_localIndex: number, row: T): any => {
    const key = this.options.trackByKey;
    // Track by key when provided; otherwise by object identity — stable across virtual redraws.
    return key ? row[key] : row;
  };

  trackByColumn = (index: number, column: JxColumn<T>): any =>
    column.key ?? index;
}
