import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { UxDirectivesModule } from 'ux-directives';
import { JxTableComponent } from './components/jx-table/jx-table.component';
import { JxGridComponent } from './components/jx-grid/jx-grid.component';
import { JxCellHostComponent } from './components/jx-cell-host/jx-cell-host.component';
import { JxCellEditableDirective } from './directives/jx-cell-editable.directive';
import { TextCellComponent } from './components/cells/text-cell/text-cell.component';
import { NumberCellComponent } from './components/cells/number-cell/number-cell.component';
import { CheckboxCellComponent } from './components/cells/checkbox-cell/checkbox-cell.component';
import { FormulaCellComponent } from './components/cells/formula-cell/formula-cell.component';
import { ButtonCellComponent } from './components/cells/button-cell/button-cell.component';
import { AttachmentCellComponent } from './components/cells/attachment-cell/attachment-cell.component';
import { JxCellRegistryService } from './services/jx-cell-registry.service';
import { JxAddressService } from './services/jx-address.service';
import { JxFormulaService } from './services/jx-formula.service';

/**
 * Angular NgModule that provides the `jx-cell` library.
 *
 * Import `JxCellModule` once in your application's `AppModule` (or any feature
 * module where the grid is used) to make the `<jx-table>` and `<jx-grid>`
 * components available.
 *
 * **Peer services** (`JxAddressService`, `JxFormulaService`) are provided in the
 * Angular root injector (`providedIn: 'root'`), so they do **not** need to be
 * listed in `providers`.
 *
 * **Per-instance service** (`JxWorkbookService`) is provided via the component's
 * own `providers` array — each `<jx-table>` element gets its own isolated
 * workbook instance automatically.
 *
 * @example
 * // app.module.ts
 * import { JxCellModule } from 'jx-cell';
 *
 * @NgModule({
 *   imports: [BrowserModule, JxCellModule],
 * })
 * export class AppModule {}
 *
 * // any template
 * // <jx-table [options]="gridOptions" (ready)="onReady($event)"></jx-table>
 * // <jx-grid [data]="rows" [columns]="columns" [options]="opts"></jx-grid>
 */
@NgModule({
  declarations: [
    JxTableComponent,
    JxGridComponent,
    JxCellHostComponent,
    JxCellEditableDirective,
    TextCellComponent,
    NumberCellComponent,
    CheckboxCellComponent,
    FormulaCellComponent,
    ButtonCellComponent,
    AttachmentCellComponent,
  ],
  imports: [CommonModule, FormsModule, UxDirectivesModule],
  providers: [JxCellRegistryService],
  exports: [
    JxTableComponent,
    JxGridComponent,
  ],
})
export class JxCellModule {
  constructor(registry: JxCellRegistryService) {
    registry.register('text', TextCellComponent);
    registry.register('number', NumberCellComponent);
    registry.register('checkbox', CheckboxCellComponent);
    registry.register('formula', FormulaCellComponent);
    registry.register('button', ButtonCellComponent);
    registry.register('attachment', AttachmentCellComponent);
  }
}
