import {
  Component,
  ComponentRef,
  EventEmitter,
  Input,
  OnChanges,
  OnDestroy,
  Output,
  SimpleChanges,
  Type,
  ViewChild,
  ViewContainerRef,
} from "@angular/core";
import { Subscription } from "rxjs";

import { JxCellContext } from "../../models/jx-cell-context.model";
import { JxCellComponent } from "../../models/jx-cell-component.interface";
import { JxCellRegistryService } from "../../services/jx-cell-registry.service";

@Component({
  standalone: false,
  selector: "jx-cell-host",
  template: "<ng-template #container></ng-template>",
  styleUrls: ["./jx-cell-host.component.scss"],
})
export class JxCellHostComponent implements OnChanges, OnDestroy {
  @Input() context!: JxCellContext;

  @Output() valueChange = new EventEmitter<any>();
  @Output() action = new EventEmitter<any>();

  @ViewChild("container", { read: ViewContainerRef, static: true })
  container!: ViewContainerRef;

  private componentRef?: ComponentRef<JxCellComponent>;
  private subscriptions = new Subscription();

  constructor(private registry: JxCellRegistryService) {}

  ngOnChanges(changes: SimpleChanges): void {
    if (changes["context"]) {
      this.render();
    }
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
    this.componentRef?.destroy();
  }

  private render(): void {
    this.container.clear();
    this.subscriptions.unsubscribe();
    this.subscriptions = new Subscription();

    const componentType = this.resolveComponent();

    if (!componentType) {
      return;
    }

    this.componentRef = this.container.createComponent(componentType);
    this.componentRef.instance.context = this.context;

    if (this.componentRef.instance.valueChange) {
      this.subscriptions.add(
        this.componentRef.instance.valueChange.subscribe((value) => {
          this.valueChange.emit(value);
        }),
      );
    }

    if (this.componentRef.instance.action) {
      this.subscriptions.add(
        this.componentRef.instance.action.subscribe((event) => {
          this.action.emit(event);
        }),
      );
    }

    this.componentRef.changeDetectorRef.detectChanges();
  }

  private resolveComponent(): Type<JxCellComponent> | null {
    if (this.context.column.component) {
      return this.context.column.component as Type<JxCellComponent>;
    }

    const type = this.context.column.type ?? "text";
    return this.registry.get(type);
  }
}
